// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address anyAddr) public {
        // Ensure we don't accidentally call onlyOwner functions as owner
        vm.assume(anyAddr != address(this));
        // Call a public function that does not change ownership
        // We use addReward with a dummy token address to trigger the bug
        // The reference C's owner() returns the deployer; mutant returns 0
        address ownerBefore = c.owner();
        // The rule: owner() returns the deployer address (this contract)
        assertTrue(ownerBefore == address(this));
    }
}

